1992: unsafe impl<#[may_dangle] T: ?Sized, A: Allocator> Drop for Box<T, A> {
1993:     #[inline]
1994:     fn drop(&mut self) {
1995:         // the T in the Box is dropped by the compiler before the destructor is run
1996: 
